export const MIGRATIONS: Record<string, Array<{ version: string; sql: string }>> = {"pulse":[{"version":"0001_pulse","sql":"-- =============================================================================\n-- pulse 0001 — Realtime events API (the plugin's OWN database, ADR 0007 and ADR 0023)\n--\n-- Apply to the pulse database (e.g. u962314563_pulse), NOT the platform database:\n--   pnpm db:migrate --plugin pulse     (uses PULSE_DB_*)\n--   or import this file in phpMyAdmin with that database selected.\n--\n-- Secrets are never stored: an app's secret key is derived from PULSE_MASTER_KEY and a random\n-- salt (secret_salt), shown once, and checked by deriving it again. IP addresses are stored only\n-- as keyed hashes. user ids are the platform's user ids (no cross-database foreign keys).\n-- SAFE TO RE-RUN.\n-- =============================================================================\n\nSET NAMES utf8mb4;\n\nCREATE TABLE IF NOT EXISTS schema_migrations (\n  version     VARCHAR(100) NOT NULL,\n  applied_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (version)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- A member's plan beyond the standard subscription (set by DevQuake, e.g. after a \"full access\"\n-- request). No row = standard.\nCREATE TABLE IF NOT EXISTS accounts (\n  user_id     INT UNSIGNED NOT NULL,\n  plan        ENUM('standard', 'full') NOT NULL DEFAULT 'standard',\n  note        VARCHAR(200) NULL,\n  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (user_id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- An API service (\"app\") of one member. Never shared with other members.\nCREATE TABLE IF NOT EXISTS apps (\n  id                 INT UNSIGNED NOT NULL AUTO_INCREMENT,\n  user_id            INT UNSIGNED NOT NULL,\n  name               VARCHAR(80)  NOT NULL,\n  public_key         VARCHAR(40)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  secret_salt        CHAR(32)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  secret_hint        CHAR(4)      CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  -- After a rotation the previous secret keeps working until prev_secret_until (a grace period).\n  prev_secret_salt   CHAR(32)     CHARACTER SET ascii COLLATE ascii_bin NULL,\n  prev_secret_until  DATETIME     NULL,\n  secret_rotated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  browser_publish    TINYINT(1)   NOT NULL DEFAULT 0,\n  strict_schema      TINYINT(1)   NOT NULL DEFAULT 0,\n  allow_localhost    TINYINT(1)   NOT NULL DEFAULT 1,\n  -- Optional: the only IP addresses the secret key may be used from (comma separated).\n  server_ips         VARCHAR(400) NULL,\n  paused             TINYINT(1)   NOT NULL DEFAULT 0,\n  created_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY ux_apps_public_key (public_key),\n  KEY ix_apps_user (user_id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Websites whose browsers may use the app's public key. An origin works once verified with a\n-- DNS TXT record (localhost needs no verification, if the app allows it).\nCREATE TABLE IF NOT EXISTS app_origins (\n  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,\n  app_id        INT UNSIGNED NOT NULL,\n  origin        VARCHAR(200) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,\n  verify_token  CHAR(32)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  verified_at   DATETIME     NULL,\n  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY ux_app_origins (app_id, origin),\n  KEY ix_app_origins_origin (origin),\n  CONSTRAINT fk_app_origins_app FOREIGN KEY (app_id) REFERENCES apps (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- The member's own key:value structure per event name: fields = JSON array of\n-- {\"key\", \"type\": \"string\"|\"number\"|\"boolean\", \"required\"}.\nCREATE TABLE IF NOT EXISTS event_types (\n  app_id      INT UNSIGNED NOT NULL,\n  name        VARCHAR(64)  CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  fields      TEXT         NOT NULL,\n  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (app_id, name),\n  CONSTRAINT fk_event_types_app FOREIGN KEY (app_id) REFERENCES apps (id) ON DELETE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Published events, kept for a short history (reconnecting clients catch up), then pruned.\n-- No foreign key: written very often; removed with the app by the plugin.\nCREATE TABLE IF NOT EXISTS events (\n  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  app_id      INT UNSIGNED    NOT NULL,\n  channel     VARCHAR(64)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  event       VARCHAR(64)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  data        TEXT            NOT NULL,\n  source      ENUM('server', 'browser', 'token', 'console') NOT NULL,\n  -- The `sub` of the client token that sent it (who it is in the member's own app).\n  sender      VARCHAR(64)     NULL,\n  created_at  DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),\n  PRIMARY KEY (id),\n  KEY ix_events_app (app_id, id),\n  KEY ix_events_created (created_at)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Usage per app and UTC day (limits and the dashboard).\nCREATE TABLE IF NOT EXISTS usage_daily (\n  app_id    INT UNSIGNED NOT NULL,\n  day       DATE         NOT NULL,\n  events    INT UNSIGNED NOT NULL DEFAULT 0,\n  rejected  INT UNSIGNED NOT NULL DEFAULT 0,\n  streams   INT UNSIGNED NOT NULL DEFAULT 0,\n  polls     INT UNSIGNED NOT NULL DEFAULT 0,\n  PRIMARY KEY (app_id, day)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Where the secret key was used from (keyed hashes of IP addresses), to spot a shared key.\nCREATE TABLE IF NOT EXISTS server_ips (\n  app_id   INT UNSIGNED NOT NULL,\n  day      DATE         NOT NULL,\n  ip_hash  CHAR(16)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  PRIMARY KEY (app_id, day, ip_hash)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Refused calls and key changes, shown to the owner.\nCREATE TABLE IF NOT EXISTS security_log (\n  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  app_id      INT UNSIGNED    NOT NULL,\n  kind        VARCHAR(32)     NOT NULL,\n  detail      VARCHAR(200)    NULL,\n  created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY ix_security_log_app (app_id, id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Open live connections (all server processes), for the per-app connection limit.\nCREATE TABLE IF NOT EXISTS streams (\n  id         CHAR(16)     CHARACTER SET ascii COLLATE ascii_bin NOT NULL,\n  app_id     INT UNSIGNED NOT NULL,\n  opened_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  seen_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY ix_streams_app (app_id, seen_at)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nINSERT IGNORE INTO schema_migrations (version) VALUES ('0001_pulse');\n"},{"version":"0002_api_calls","sql":"-- =============================================================================\n-- Pulse 0002 — API call log and totals\n--\n-- api_calls   one row per call of the developer API (/v1/events, /v1/stream, /v1/poll):\n--             when, which service (NULL when the key was not recognised), route, method,\n--             HTTP status, source and duration. No keys, tokens, bodies or addresses.\n--             Cleaned by an admin in the app (now, or automatically every N days).\n-- api_totals  the number of calls, kept apart from the log so cleaning never changes it:\n--             app_id 0 = every call ever made to Pulse, others = one API service (removed with\n--             the service).\n-- settings    app-wide settings, e.g. the automatic clean-up interval of the call log.\n--\n-- SAFE TO RE-RUN.\n-- =============================================================================\n\nSET NAMES utf8mb4;\n\nCREATE TABLE IF NOT EXISTS api_calls (\n  id          BIGINT UNSIGNED   NOT NULL AUTO_INCREMENT,\n  app_id      INT UNSIGNED      NULL,\n  called_at   DATETIME(3)       NOT NULL DEFAULT CURRENT_TIMESTAMP(3),\n  method      VARCHAR(8)        CHARACTER SET ascii NOT NULL,\n  route       VARCHAR(40)       CHARACTER SET ascii NOT NULL,\n  status      SMALLINT UNSIGNED NOT NULL,\n  -- server / browser / token (NULL when the caller was not identified).\n  source      VARCHAR(16)       CHARACTER SET ascii NULL,\n  duration_ms INT UNSIGNED      NOT NULL DEFAULT 0,\n  PRIMARY KEY (id),\n  KEY ix_api_calls_app (app_id, id),\n  KEY ix_api_calls_time (called_at)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS api_totals (\n  app_id    INT UNSIGNED    NOT NULL,\n  calls     BIGINT UNSIGNED NOT NULL DEFAULT 0,\n  refused   BIGINT UNSIGNED NOT NULL DEFAULT 0,\n  first_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_at   DATETIME        NULL,\n  PRIMARY KEY (app_id)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\nCREATE TABLE IF NOT EXISTS settings (\n  name        VARCHAR(40)   CHARACTER SET ascii NOT NULL,\n  value       VARCHAR(200)  NOT NULL,\n  updated_at  DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  updated_by  INT UNSIGNED  NULL,\n  PRIMARY KEY (name)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- Clean the call log automatically: entries older than 30 days (0 = only by hand).\nINSERT IGNORE INTO settings (name, value) VALUES ('call_log_days', '30');\n\nINSERT IGNORE INTO schema_migrations (version) VALUES ('0002_api_calls');\n"},{"version":"0003_pulse_demo","sql":"-- =============================================================================\n-- pulse 0003 — The live demo service (the plugin's OWN database, ADR 0029)\n--\n-- Apply to the pulse database, NOT the platform database:\n--   pnpm db:migrate --plugin pulse     (uses PULSE_DB_*)\n--   or import this file in phpMyAdmin with that database selected.\n--\n-- apps.demo = 1 marks DevQuake's own demo service (user_id 0, created by the app on first use):\n-- members try Pulse between two of their browsers on their own private channel, with client\n-- tokens signed by the demo service, without using their own services or plan. It is never\n-- listed as anyone's service, and its events are removed after an hour.\n-- SAFE TO RE-RUN.\n-- =============================================================================\n\nSET NAMES utf8mb4;\n\nSET @dq_sql := IF(\n  (SELECT COUNT(*) FROM information_schema.COLUMNS\n    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'apps' AND COLUMN_NAME = 'demo') = 0,\n  'ALTER TABLE apps ADD COLUMN demo TINYINT(1) NOT NULL DEFAULT 0 AFTER paused',\n  'DO 0');\nPREPARE dq_stmt FROM @dq_sql;\nEXECUTE dq_stmt;\nDEALLOCATE PREPARE dq_stmt;\n\nINSERT IGNORE INTO schema_migrations (version) VALUES ('0003_pulse_demo');\n"}]};

export const CHANGELOGS: Record<string, Partial<Record<'en' | 'de' | 'ro' | 'hu', string>>> = {"pulse":{"en":"# Changelog — Pulse\n\n## 0.6.0\n\n- Pulse can now run on your own server (DevQuake self-hosted): there, every member gets the full plan.\n\n## 0.5.1\n\n- “Back” links now return to the page you came from, with its filters and where you had scrolled to.\n\n## 0.5.0\n\n- The app’s card on DevQuake and its front page now show how many members use it and its totals: API services, events today.\n\n0.4.1\n\n- People who do not use the app yet now see what it does on its front page, with a link to the user manual, and shared links show the app’s own picture.\n\n## 0.4.0\n\n- Check it live: open the new demo in two browsers (signed in to the same account) and send a message or your own JSON from one to the other through the real Pulse API. The other browser shows what arrived and how long it took, from the sender to the server, from the server to the browser and in total, with the average, fastest and slowest. Free on every plan, on a private channel only you can use.\n\n## 0.3.0\n\n- API calls are counted: your service's page shows how many calls it received in total, in short form (like 1.2K or 100K; the exact number when you point at it), how many were refused, and the latest calls with their answer and how long they took.\n- For DevQuake admins: the totals of all services, the size of the call log, and cleaning the log now or automatically every 1, 7, 30 or 90 days. Cleaning the log never changes the totals. When Pulse cannot start, admins now see which setting is missing.\n\n## 0.2.0\n\n- Add the app to your home screen: on phones and tablets, the new button in the toolbar puts the app’s icon (its logo with the DevQuake badge) on your home screen, so it opens like an app.\n\n## 0.1.0\n\n- Create API services and get a public key for your web pages and a secret key for your server (shown once, never stored; make a new one any time, the old one keeps working for 24 hours).\n- Send events with your own key:value data and receive them live in every connected browser, with a polling fallback where live connections are blocked; clients that reconnect catch up on what they missed.\n- Describe your own data structure per event (keys, types, required) and optionally refuse everything else.\n- Security: the public key only works on websites you verified with a DNS record, the secret key is refused in web pages and can be tied to your servers' addresses, private channels need short-lived client tokens, and a security log warns you when a key seems to be shared.\n- A live test to try everything with two devices, ready-to-copy code, and usage per day. Try it free for 24 hours (slower on purpose) or subscribe; ask us for full access.\n","de":"# Änderungen — Pulse\n\n## 0.6.0\n\n- Pulse läuft jetzt auch auf deinem eigenen Server (DevQuake selbst gehostet): Dort bekommt jedes Mitglied den vollen Plan.\n\n## 0.5.1\n\n- „Zurück“-Links führen jetzt zu der Seite, von der du kamst, mit ihren Filtern und der Stelle, bis zu der du gescrollt hattest.\n\n## 0.5.0\n\n- Die Karte der App auf DevQuake und ihre Startseite zeigen jetzt, wie viele Mitglieder sie nutzen, und ihre Zahlen: API-Dienste, Ereignisse heute.\n\n0.4.1\n\n- Wer die App noch nicht nutzt, sieht jetzt auf ihrer Startseite, was sie kann, mit einem Link zum Benutzerhandbuch, und geteilte Links zeigen das eigene Bild der App.\n\n## 0.4.0\n\n- Live ausprobieren: Öffne die neue Demo in zwei Browsern (mit demselben Konto angemeldet) und sende eine Nachricht oder dein eigenes JSON vom einen zum anderen über die echte Pulse-API. Der andere Browser zeigt, was angekommen ist und wie lange es gedauert hat, vom Absender zum Server, vom Server zum Browser und insgesamt, mit Durchschnitt, schnellstem und langsamstem Wert. Kostenlos in jedem Tarif, auf einem privaten Kanal, den nur du nutzen kannst.\n\n## 0.3.0\n\n- API-Aufrufe werden gezählt: Die Seite deines Dienstes zeigt, wie viele Aufrufe er insgesamt erhalten hat, in Kurzform (etwa 1,2K oder 100K; die genaue Zahl, wenn du darauf zeigst), wie viele abgelehnt wurden, und die letzten Aufrufe mit Antwort und Dauer.\n- Für DevQuake-Admins: die Summen aller Dienste, die Größe des Aufrufprotokolls und das Bereinigen des Protokolls jetzt oder automatisch alle 1, 7, 30 oder 90 Tage. Das Bereinigen ändert die Summen nie. Wenn Pulse nicht starten kann, sehen Admins jetzt, welche Einstellung fehlt.\n\n## 0.2.0\n\n- Die App auf den Home-Bildschirm legen: Auf Handys und Tablets legt der neue Knopf in der Werkzeugleiste das Symbol der App (ihr Logo mit dem DevQuake-Abzeichen) auf deinen Home-Bildschirm, sodass sie sich wie eine App öffnet.\n\n## 0.1.0\n\n- Lege API-Dienste an und bekomme einen öffentlichen Schlüssel für deine Webseiten und einen geheimen Schlüssel für deinen Server (einmal angezeigt, nie gespeichert; jederzeit erneuerbar, der alte funktioniert noch 24 Stunden).\n- Sende Events mit deinen eigenen Schlüssel-Wert-Daten und empfange sie live in jedem verbundenen Browser, mit Abfragen als Ausweg, wo Live-Verbindungen blockiert sind; neu verbundene Clients holen Verpasstes nach.\n- Beschreibe deine eigene Datenstruktur pro Event (Schlüssel, Typen, Pflicht) und lehne auf Wunsch alles andere ab.\n- Sicherheit: Der öffentliche Schlüssel funktioniert nur auf Websites, die du per DNS-Eintrag bestätigt hast, der geheime Schlüssel wird in Webseiten abgelehnt und kann an die Adressen deiner Server gebunden werden, private Kanäle brauchen kurzlebige Client-Tokens, und ein Sicherheitsprotokoll warnt dich, wenn ein Schlüssel geteilt zu sein scheint.\n- Ein Live-Test, um alles mit zwei Geräten auszuprobieren, Code zum Kopieren und die Nutzung pro Tag. Teste es 24 Stunden kostenlos (absichtlich langsamer) oder abonniere es; frag uns nach vollem Zugang.\n","ro":"# Noutăți — Pulse\n\n## 0.6.0\n\n- Pulse poate rula acum pe propriul tău server (DevQuake găzduit de tine): acolo fiecare membru primește planul complet.\n\n## 0.5.1\n\n- Linkurile „Înapoi” te duc acum la pagina de unde ai venit, cu filtrele ei și acolo unde derulaseși.\n\n## 0.5.0\n\n- Cardul aplicației pe DevQuake și pagina ei de start arată acum câți membri o folosesc și totalurile ei: servicii API, evenimente azi.\n\n0.4.1\n\n- Cine nu folosește încă aplicația vede acum pe prima ei pagină ce face, cu un link spre manualul de utilizare, iar linkurile distribuite arată imaginea aplicației.\n\n## 0.4.0\n\n- Încearcă live: deschide noul demo în două browsere (autentificate cu același cont) și trimite un mesaj sau propriul JSON de la unul la altul prin API-ul Pulse real. Celălalt browser arată ce a sosit și cât a durat, de la expeditor la server, de la server la browser și în total, cu media, cel mai rapid și cel mai lent. Gratuit în orice plan, pe un canal privat pe care doar tu îl poți folosi.\n\n## 0.3.0\n\n- Apelurile API sunt numărate: pagina serviciului tău arată câte apeluri a primit în total, în formă scurtă (de exemplu 1,2K sau 100K; numărul exact când îndrepți cursorul spre el), câte au fost refuzate și ultimele apeluri, cu răspunsul și durata lor.\n- Pentru administratorii DevQuake: totalurile tuturor serviciilor, mărimea jurnalului de apeluri și curățarea jurnalului acum sau automat la fiecare 1, 7, 30 sau 90 de zile. Curățarea nu schimbă niciodată totalurile. Când Pulse nu poate porni, administratorii văd acum ce setare lipsește.\n\n## 0.2.0\n\n- Adaugă aplicația pe ecranul principal: pe telefoane și tablete, noul buton din bara de instrumente pune pictograma aplicației (sigla ei cu insigna DevQuake) pe ecranul principal, ca să se deschidă ca o aplicație.\n\n## 0.1.0\n\n- Creează servicii API și primește o cheie publică pentru paginile tale web și o cheie secretă pentru serverul tău (afișată o dată, niciodată stocată; o poți reînnoi oricând, cea veche mai merge 24 de ore).\n- Trimite evenimente cu propriile date cheie:valoare și primește-le live în fiecare browser conectat, cu interogare ca alternativă unde conexiunile live sunt blocate; clienții reconectați recuperează ce au ratat.\n- Descrie propria structură de date pentru fiecare eveniment (chei, tipuri, obligatorii) și, opțional, refuză orice altceva.\n- Securitate: cheia publică funcționează doar pe site-urile verificate cu o înregistrare DNS, cheia secretă e refuzată în pagini web și poate fi legată de adresele serverelor tale, canalele private au nevoie de tokenuri de client de scurtă durată, iar un jurnal de securitate te avertizează când o cheie pare partajată.\n- Un test live pentru a încerca totul cu două dispozitive, cod gata de copiat și utilizarea pe zile. Încearcă-l gratuit 24 de ore (intenționat mai lent) sau abonează-te; cere-ne acces complet.\n","hu":"# Változások — Pulse\n\n## 0.6.0\n\n- A Pulse mostantól a saját szervereden is futhat (saját üzemeltetésű DevQuake): ott minden tag a teljes csomagot kapja.\n\n## 0.5.1\n\n- A „Vissza” linkek most arra az oldalra visznek, ahonnan jöttél, a szűrőivel és oda, ameddig görgettél.\n\n## 0.5.0\n\n- Az alkalmazás kártyája a DevQuake-en és a kezdőoldala most megmutatja, hány tag használja, és a számait: API-szolgáltatás, mai esemény.\n\n0.4.1\n\n- Aki még nem használja az alkalmazást, most a kezdőlapján látja, mire jó, a felhasználói kézikönyv linkjével, a megosztott linkek pedig az alkalmazás saját képét mutatják.\n\n## 0.4.0\n\n- Próbáld ki élőben: nyisd meg az új demót két böngészőben (ugyanazzal a fiókkal bejelentkezve), és küldj üzenetet vagy saját JSON-t az egyikből a másikba a valódi Pulse API-n keresztül. A másik böngésző mutatja, mi érkezett és mennyi ideig tartott, a küldőtől a szerverig, a szervertől a böngészőig és összesen, átlaggal, a leggyorsabbal és a leglassabbal. Minden csomagban ingyenes, egy csak általad használható privát csatornán.\n\n## 0.3.0\n\n- Az API-hívásokat számoljuk: a szolgáltatásod oldala megmutatja, összesen hány hívást kapott, rövid formában (például 1,2K vagy 100K; a pontos számot, ha rámutatsz), hányat utasított el, és a legutóbbi hívásokat a válasszal és az időtartammal.\n- A DevQuake adminjainak: az összes szolgáltatás összesítése, a hívásnapló mérete, és a napló törlése most vagy automatikusan 1, 7, 30 vagy 90 naponta. A törlés soha nem változtat az összesítéseken. Ha a Pulse nem tud elindulni, az adminok most látják, melyik beállítás hiányzik.\n\n## 0.2.0\n\n- Tedd ki az alkalmazást a kezdőképernyőre: telefonon és táblagépen az eszköztár új gombja kiteszi az alkalmazás ikonját (a logóját a DevQuake-jelvénnyel) a kezdőképernyődre, így alkalmazásként nyílik meg.\n\n## 0.1.0\n\n- Hozz létre API-szolgáltatásokat, és kapj nyilvános kulcsot a weboldalaidhoz, valamint titkos kulcsot a szerveredhez (egyszer látható, soha nem tároljuk; bármikor újat készíthetsz, a régi még 24 óráig működik).\n- Küldj eseményeket saját kulcs–érték adatokkal, és fogadd őket élőben minden csatlakozott böngészőben, lekérdezéses tartalékkal ott, ahol az élő kapcsolat tiltott; az újracsatlakozó kliensek pótolják, amit elmulasztottak.\n- Írd le a saját adatszerkezetedet eseményenként (kulcsok, típusok, kötelezőség), és ha szeretnéd, utasíts el minden mást.\n- Biztonság: a nyilvános kulcs csak DNS-rekorddal igazolt weboldalakon működik, a titkos kulcsot weboldalakban elutasítjuk, és a szervereid címeihez köthető, a privát csatornákhoz rövid életű kliens-tokenek kellenek, és a biztonsági napló figyelmeztet, ha egy kulcs megosztottnak tűnik.\n- Élő teszt, hogy két eszközzel mindent kipróbálhass, másolható kód és napi használat. Próbáld ki 24 órán át ingyen (szándékosan lassabban), vagy fizess elő; kérj tőlünk teljes hozzáférést.\n"}};
